    `uvm_do_with(req, {clr == 0; control == 2'b11; parallel_in == 8'hA5;}) // Setup
    `uvm_do_with(req, {clr == 0; control == 2'b01; serial_in_left == 1;})  // Right shift
    `uvm_do_with(req, {clr == 0; control == 2'b10; serial_in_right == 0;}) // Left shift

    // 4. Constrained Random Operations
