class usr_monitor extends uvm_monitor;
  `uvm_component_utils(usr_monitor)

  virtual usr_if vif;
  uvm_analysis_port #(usr_seq_item) ap;

  function new(string name="usr_monitor", uvm_component parent=null);
    super.new(name, parent);
    ap = new("ap", this);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if(!uvm_config_db#(virtual usr_if)::get(this, "", "vif", vif))
      `uvm_fatal("MON", "Failed to obtain virtual interface from config db")
  endfunction

  task run_phase(uvm_phase phase);
    usr_seq_item item;
    forever begin
      @(posedge vif.clk);
      #1; // Delay to sample stable signals post NBA region to avoid race conditions

      item = usr_seq_item::type_id::create("item");
      
      // Capture inputs currently driving the DUT in this cycle
      item.clr             = vif.clr;
      item.control         = vif.control;
      item.parallel_in     = vif.parallel_in;
      item.serial_in_right = vif.serial_in_right;
      item.serial_in_left  = vif.serial_in_left;

      // Capture outputs reflecting the result of the PREVIOUS cycle's inputs
      item.serial_out_right = vif.serial_out_right;
      item.serial_out_left  = vif.serial_out_left;
      item.parallel_out     = vif.parallel_out;

      // Broadcast transaction
      ap.write(item);
    end
  endtask
