// ════════════════════════════════════════════════════════════

class usr_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(usr_scoreboard)

  uvm_analysis_imp #(usr_seq_item, usr_scoreboard) analysis_export;

  // Reference model internal state
  logic [7:0] exp_parallel_out;
  bit initialized = 0;

  function new(string name="usr_scoreboard", uvm_component parent=null);
    super.new(name, parent);
    analysis_export = new("analysis_export", this);
  endfunction

  function void write(usr_seq_item item);
    if(initialized) begin
      // Verify primary parallel output
      if(item.parallel_out !== exp_parallel_out) begin
        `uvm_error("SCB_FAIL", $sformatf("parallel_out mismatch. Exp: %0h, Act: %0h", 
                                         exp_parallel_out, item.parallel_out))
      end
      
      // Verify continuous combinational assignments
      if(item.serial_out_right !== exp_parallel_out[0]) begin
        `uvm_error("SCB_FAIL", $sformatf("serial_out_right mismatch. Exp: %0b, Act: %0b", 
                                         exp_parallel_out[0], item.serial_out_right))
      end
      
      if(item.serial_out_left !== exp_parallel_out[7]) begin
        `uvm_error("SCB_FAIL", $sformatf("serial_out_left mismatch. Exp: %0b, Act: %0b", 
                                         exp_parallel_out[7], item.serial_out_left))
      end
    end else begin
      initialized = 1;
    end

    // Compute expected state for the NEXT cycle based on current inputs
    if(item.clr) begin
      exp_parallel_out = 8'h00;
    end else begin
      case(item.control)
        2'b00: exp_parallel_out = exp_parallel_out; // Hold
        2'b01: exp_parallel_out = {item.serial_in_left, exp_parallel_out[7:1]}; // Right Shift
        2'b10: exp_parallel_out = {exp_parallel_out[6:0], item.serial_in_right}; // Left Shift
        2'b11: exp_parallel_out = item.parallel_in; // Parallel Load
      endcase
    end
  endfunction
endclass

