class usr_coverage extends uvm_subscriber #(usr_seq_item);
  `uvm_component_utils(usr_coverage)

  usr_seq_item req;

  covergroup usr_cg;
    option.per_instance = 1;

    // Track reset assertions/deassertions
    cp_clr: coverpoint req.clr {
      bins active = {1};
      bins inactive = {0};
    }

    // Track control configurations and specific transition requirements
    cp_control: coverpoint req.control {
      bins hold  = {2'b00};
      bins right = {2'b01};
      bins left  = {2'b10};
      bins load  = {2'b11};
      
      // Specifically target coverage for SVA 'p_load_then_hold'
      bins load_then_hold = (2'b11 => 2'b00);
      bins shift_right_to_left = (2'b01 => 2'b10);
      bins shift_left_to_right = (2'b10 => 2'b01);
    }

    // Track important boundaries on the parallel input bus
    cp_par_in: coverpoint req.parallel_in {
      bins min_val = {8'h00};
      bins max_val = {8'hFF};
      bins alt1    = {8'hAA};
      bins alt2    = {8'h55};
      bins others  = default;
    }

    // Ensure we see different control ops with different data loads
    cr_ctrl_par: cross cp_control, cp_par_in;
  endgroup

  function new(string name="usr_coverage", uvm_component parent=null);
    super.new(name, parent);
    usr_cg = new();
  endfunction

  function void write(usr_seq_item t);
    req = t;
    usr_cg.sample();
  endfunction
endclass

