module tb_top;
  `include "uvm_macros.svh"
  import uvm_pkg::*;

  logic clk;

  // 1. Clock Generation
  initial begin
    clk = 0;
    forever #5 clk = ~clk; // 100MHz clock frequency
  end

  // 2. Interface Instantiation (provided in design file)
  usr_if vif(clk);

  // 3. DUT Instantiation
  universal_shift_register dut (
    .clk             (clk),
    .clr             (vif.clr),
    .control         (vif.control),
    .parallel_in     (vif.parallel_in),
    .serial_in_right (vif.serial_in_right),
    .serial_in_left  (vif.serial_in_left),
    .serial_out_right(vif.serial_out_right),
    .serial_out_left (vif.serial_out_left),
    .parallel_out    (vif.parallel_out)
  );

  // 4. Test Initiation
  initial begin
    // Pass the virtual interface to UVM configuration database
    uvm_config_db#(virtual usr_if)::set(null, "*", "vif", vif);
    
    // Start the UVM test
    run_test("usr_test");
  end

  // Dump VCD waves for debugging (simulator dependent)
  initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, tb_top);
  end
endmodule

